window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2dae7d2324a64325"]={"versions": [{"id": "FIG-2dae7d2324a64325", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Konfigurationsdiagramm des AUTOSAR General Purpose Timer (GPT) Drivers im Kontext von Hardware-Taktung, Mikrocontroller-Abstraktionsschicht (MCAL) und oberen Softwareschichten (OS, I/O Hardware Abstraction).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration & Beschreibung</strong>: <code>HW Description</code> (Artefakt/Eingabe) speist den <code>Configurator</code>.</li>\n<li><strong>Software-Module / Treiber (MCAL & Obere Schichten)</strong>:</li>\n<li><code>Configurator</code>: Verteilt Konfigurationsparameter (<code>Prescaler value</code>, Zeitumrechnung <code>1 Tick ≡ x s</code>) an Treiber und Schichten.</li>\n<li><code>MCU Driver</code>: Erhält Prescaler-Werte und steuert die gemeinsame Taktinfrastruktur (<code>Configuration of shared resources</code>).</li>\n<li><code>GPT Driver</code>: Erhält Prescaler-Werte und initialisiert/konfiguriert GPT-spezifische Hardwareressourcen (<code>Init</code>, <code>Configuration of GPT resources</code>). Übergibt Zeitinformationen (<code>Ticks</code>) an übergeordnete Schichten.</li>\n<li><code>I/O Hardware Abstraction</code> & <code>OS</code>: Empfangen <code>Ticks</code> von <code>GPT Driver</code> sowie Zeitbasisvorgaben (<code>1 Tick ≡ x s</code>) vom <code>Configurator</code>.</li>\n<li><strong>Hardware-Entitäten (µC)</strong>:</li>\n<li>Oszillator/Quarz speist <code>PLL</code>.</li>\n<li>Gemeinsamer Takt-<code>Prescaler</code> (nach <code>PLL</code>), versorgt <code>Module1 HW</code>, <code>GPT Prescaler</code> und <code>Module2 HW</code>.</li>\n<li>GPT-Hardwarepfad: Bestehend aus modulspezifischem <code>GPT Prescaler</code> und <code>GPT HW</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Konfigurationsphase</strong>: Der <code>Configurator</code> liest die Hardware-Beschreibung (<code>HW Description</code>) ein und bestimmt die Taktteiler- und Prescaler-Werte. Er übermittelt <code>Prescaler value</code> an den <code>MCU Driver</code> sowie an den <code>GPT Driver</code> und legt für <code>I/O Hardware Abstraction</code> und <code>OS</code> das Taktäquivalent (<code>1 Tick ≡ x s</code>) fest.</li>\n<li><strong>Initialisierung & Hardware-Konfiguration</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>MCU Driver</code> konfiguriert die geteilten Systemressourcen (<code>PLL</code> und übergeordneten <code>Prescaler</code>).</li>\n<li>Der <code>GPT Driver</code> führt die Initialisierung durch (<code>Init</code>) und konfiguriert die dedizierten GPT-Ressourcen (<code>GPT Prescaler</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Laufzeitbetrieb</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Taktkette läuft von Quarz -> <code>PLL</code> -> zentraler <code>Prescaler</code> -> modulspezifischer <code>GPT Prescaler</code> -> <code>GPT HW</code>.</li>\n<li>Der <code>GPT Driver</code> liefert gezählte Zeiteinheiten (<code>Ticks</code>) an die <code>I/O Hardware Abstraction</code> und das <code>OS</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht die funktionale und normative Aufteilung der Verantwortlichkeiten zwischen MCU Driver und GPT Driver:</p>\n<ul class=\"fig-list\">\n<li><strong>Zuständigkeit MCU Driver</strong>: Globale Taktquellen (PLL) und gemeinsame Vorverteiler dürfen normativ nicht durch Peripherietreiber verändert werden, sondern verbleiben beim MCU Driver.</li>\n<li><strong>Zuständigkeit GPT Driver</strong>: Der GPT Driver ist strikt auf die Konfiguration der modulspezifischen GPT-Ressourcen (kanalspezifische Prescaler, Timer-Hardware) beschränkt.</li>\n<li><strong>Zeitschnittstelle zu Oberschichten</strong>: Die oberen Schichten (OS, I/O Abstraction) operieren auf Basis von Ticks, deren Zeiteinheit (<code>1 Tick ≡ x s</code>) statisch im Systemkonfigurator festgelegt wird.</li>\n</ul>"}, {"id": "FIG-aa1c7f8f7c160289", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Konfigurationsdiagramm des AUTOSAR General Purpose Timer (GPT) Drivers im Kontext von Hardware-Taktung, Mikrocontroller-Abstraktionsschicht (MCAL) und oberen Softwareschichten (OS, I/O Hardware Abstraction).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration & Beschreibung</strong>: <code>HW Description</code> (Artefakt/Eingabe) speist den <code>Configurator</code>.</li>\n<li><strong>Software-Module / Treiber (MCAL & Obere Schichten)</strong>:</li>\n<li><code>Configurator</code>: Verteilt Konfigurationsparameter (<code>Prescaler value</code>, Zeitumrechnung <code>1 Tick ≡ x s</code>) an Treiber und Schichten.</li>\n<li><code>MCU Driver</code>: Erhält Prescaler-Werte und steuert die gemeinsame Taktinfrastruktur (<code>Configuration of shared resources</code>).</li>\n<li><code>GPT Driver</code>: Erhält Prescaler-Werte und initialisiert/konfiguriert GPT-spezifische Hardwareressourcen (<code>Init</code>, <code>Configuration of GPT resources</code>). Übergibt Zeitinformationen (<code>Ticks</code>) an übergeordnete Schichten.</li>\n<li><code>I/O Hardware Abstraction</code> & <code>OS</code>: Empfangen <code>Ticks</code> von <code>GPT Driver</code> sowie Zeitbasisvorgaben (<code>1 Tick ≡ x s</code>) vom <code>Configurator</code>.</li>\n<li><strong>Hardware-Entitäten (µC)</strong>:</li>\n<li>Oszillator/Quarz speist <code>PLL</code>.</li>\n<li>Gemeinsamer Takt-<code>Prescaler</code> (nach <code>PLL</code>), versorgt <code>Module1 HW</code>, <code>GPT Prescaler</code> und <code>Module2 HW</code>.</li>\n<li>GPT-Hardwarepfad: Bestehend aus modulspezifischem <code>GPT Prescaler</code> und <code>GPT HW</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Konfigurationsphase</strong>: Der <code>Configurator</code> liest die Hardware-Beschreibung (<code>HW Description</code>) ein und bestimmt die Taktteiler- und Prescaler-Werte. Er übermittelt <code>Prescaler value</code> an den <code>MCU Driver</code> sowie an den <code>GPT Driver</code> und legt für <code>I/O Hardware Abstraction</code> und <code>OS</code> das Taktäquivalent (<code>1 Tick ≡ x s</code>) fest.</li>\n<li><strong>Initialisierung & Hardware-Konfiguration</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>MCU Driver</code> konfiguriert die geteilten Systemressourcen (<code>PLL</code> und übergeordneten <code>Prescaler</code>).</li>\n<li>Der <code>GPT Driver</code> führt die Initialisierung durch (<code>Init</code>) und konfiguriert die dedizierten GPT-Ressourcen (<code>GPT Prescaler</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Laufzeitbetrieb</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Taktkette läuft von Quarz -> <code>PLL</code> -> zentraler <code>Prescaler</code> -> modulspezifischer <code>GPT Prescaler</code> -> <code>GPT HW</code>.</li>\n<li>Der <code>GPT Driver</code> liefert gezählte Zeiteinheiten (<code>Ticks</code>) an die <code>I/O Hardware Abstraction</code> und das <code>OS</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht die funktionale und normative Aufteilung der Verantwortlichkeiten zwischen MCU Driver und GPT Driver:</p>\n<ul class=\"fig-list\">\n<li><strong>Zuständigkeit MCU Driver</strong>: Globale Taktquellen (PLL) und gemeinsame Vorverteiler dürfen normativ nicht durch Peripherietreiber verändert werden, sondern verbleiben beim MCU Driver.</li>\n<li><strong>Zuständigkeit GPT Driver</strong>: Der GPT Driver ist strikt auf die Konfiguration der modulspezifischen GPT-Ressourcen (kanalspezifische Prescaler, Timer-Hardware) beschränkt.</li>\n<li><strong>Zeitschnittstelle zu Oberschichten</strong>: Die oberen Schichten (OS, I/O Abstraction) operieren auf Basis von Ticks, deren Zeiteinheit (<code>1 Tick ≡ x s</code>) statisch im Systemkonfigurator festgelegt wird.</li>\n</ul>"}, {"id": "FIG-d18332a36d9f3cb0", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Konfigurationsdiagramm des AUTOSAR General Purpose Timer (GPT) Drivers im Kontext von Hardware-Taktung, Mikrocontroller-Abstraktionsschicht (MCAL) und oberen Softwareschichten (OS, I/O Hardware Abstraction).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration & Beschreibung</strong>: <code>HW Description</code> (Artefakt/Eingabe) speist den <code>Configurator</code>.</li>\n<li><strong>Software-Module / Treiber (MCAL & Obere Schichten)</strong>:</li>\n<li><code>Configurator</code>: Verteilt Konfigurationsparameter (<code>Prescaler value</code>, Zeitumrechnung <code>1 Tick ≡ x s</code>) an Treiber und Schichten.</li>\n<li><code>MCU Driver</code>: Erhält Prescaler-Werte und steuert die gemeinsame Taktinfrastruktur (<code>Configuration of shared resources</code>).</li>\n<li><code>GPT Driver</code>: Erhält Prescaler-Werte und initialisiert/konfiguriert GPT-spezifische Hardwareressourcen (<code>Init</code>, <code>Configuration of GPT resources</code>). Übergibt Zeitinformationen (<code>Ticks</code>) an übergeordnete Schichten.</li>\n<li><code>I/O Hardware Abstraction</code> & <code>OS</code>: Empfangen <code>Ticks</code> von <code>GPT Driver</code> sowie Zeitbasisvorgaben (<code>1 Tick ≡ x s</code>) vom <code>Configurator</code>.</li>\n<li><strong>Hardware-Entitäten (µC)</strong>:</li>\n<li>Oszillator/Quarz speist <code>PLL</code>.</li>\n<li>Gemeinsamer Takt-<code>Prescaler</code> (nach <code>PLL</code>), versorgt <code>Module1 HW</code>, <code>GPT Prescaler</code> und <code>Module2 HW</code>.</li>\n<li>GPT-Hardwarepfad: Bestehend aus modulspezifischem <code>GPT Prescaler</code> und <code>GPT HW</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Konfigurationsphase</strong>: Der <code>Configurator</code> liest die Hardware-Beschreibung (<code>HW Description</code>) ein und bestimmt die Taktteiler- und Prescaler-Werte. Er übermittelt <code>Prescaler value</code> an den <code>MCU Driver</code> sowie an den <code>GPT Driver</code> und legt für <code>I/O Hardware Abstraction</code> und <code>OS</code> das Taktäquivalent (<code>1 Tick ≡ x s</code>) fest.</li>\n<li><strong>Initialisierung & Hardware-Konfiguration</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>MCU Driver</code> konfiguriert die geteilten Systemressourcen (<code>PLL</code> und übergeordneten <code>Prescaler</code>).</li>\n<li>Der <code>GPT Driver</code> führt die Initialisierung durch (<code>Init</code>) und konfiguriert die dedizierten GPT-Ressourcen (<code>GPT Prescaler</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Laufzeitbetrieb</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Taktkette läuft von Quarz -> <code>PLL</code> -> zentraler <code>Prescaler</code> -> modulspezifischer <code>GPT Prescaler</code> -> <code>GPT HW</code>.</li>\n<li>Der <code>GPT Driver</code> liefert gezählte Zeiteinheiten (<code>Ticks</code>) an die <code>I/O Hardware Abstraction</code> und das <code>OS</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht die funktionale und normative Aufteilung der Verantwortlichkeiten zwischen MCU Driver und GPT Driver:</p>\n<ul class=\"fig-list\">\n<li><strong>Zuständigkeit MCU Driver</strong>: Globale Taktquellen (PLL) und gemeinsame Vorverteiler dürfen normativ nicht durch Peripherietreiber verändert werden, sondern verbleiben beim MCU Driver.</li>\n<li><strong>Zuständigkeit GPT Driver</strong>: Der GPT Driver ist strikt auf die Konfiguration der modulspezifischen GPT-Ressourcen (kanalspezifische Prescaler, Timer-Hardware) beschränkt.</li>\n<li><strong>Zeitschnittstelle zu Oberschichten</strong>: Die oberen Schichten (OS, I/O Abstraction) operieren auf Basis von Ticks, deren Zeiteinheit (<code>1 Tick ≡ x s</code>) statisch im Systemkonfigurator festgelegt wird.</li>\n</ul>"}], "trans": [{"from": "FIG-2dae7d2324a64325", "to": "FIG-aa1c7f8f7c160289", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-aa1c7f8f7c160289", "to": "FIG-d18332a36d9f3cb0", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
